str15:			db "; ", 0
str16:			db "a; b; c; b", 0
str17:			db "a,,c,", 0
str18:			db "hello", 0
str19:			db "olleh", 0
str20:			db "cba", 0
str21:			db "10", 0
str22:			db "777", 0
str23:			db "177777", 0
